  ?s brick:hasLabel "DataCenter_top_ZN_6" ;
     a brick:Zone ;
     ref:hasExternalReference ?uri ;
     ref:hasTimeseriesId ?id .
}

SELECT ?s ?label WHERE {
  ?s a brick:Zone ; brick:hasLabel ?label .
  FILTER (?label LIKE "%DataCenter_top_ZN_6%")
}

SELECT ?s ?label WHERE {
  ?s a brick:Zone ; brick:hasLabel ?label .
  FILTER (?label LIKE "%ZN_6%")
}

SELECT ?s ?label ?id ?class WHERE {
  ?s brick:hasLabel ?label .
  FILTER (?label LIKE "%DataCenter_top_ZN_6%")
  OPTIONAL { ?s ref:hasTimeseriesId ?id }
  OPTIONAL { ?s a ?class }
}

SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
  ?s a brick:Zone .
} LIMIT 200

SELECT ?s ?class ?id WHERE {
  ?s a ?class .
  ?s brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09> .
  OPTIONAL { ?s ref:hasTimeseriesId ?id }
}

